// ── YAML serializer (hand-written) ──
function yamlScalar(v) {
  v = String(v == null ? "" : v);
  if (v === "") return "''";
  var needs = /^[\s]|[\s]$/.test(v) ||
    /[:#{}\[\],&*!|>'"%@`]/.test(v) ||
    /^[-?]/.test(v) ||
    /^(true|false|null|yes|no|on|off|~)$/i.test(v) ||
    /^[0-9.+-]+$/.test(v);
  if (needs) return "'" + v.replace(/'/g, "''") + "'";
  return v;
}

function buildYaml(st) {
  var L = [];
  L.push("title: " + yamlScalar(st.title));
  L.push("id: " + (st.id || ""));
  if (st.status) L.push("status: " + st.status);
  if (st.description) {
    if (/\n/.test(st.description)) {
      L.push("description: |");
      st.description.split("\n").forEach(function (ln) { L.push("    " + ln); });
    } else {
      L.push("description: " + yamlScalar(st.description));
    }
  }
  if (st.author) L.push("author: " + yamlScalar(st.author));
  if (st.date) L.push("date: " + yamlScalar(st.date));
  if (st.references && st.references.length) {
    L.push("references:");
    st.references.forEach(function (r) { L.push("    - " + yamlScalar(r)); });
  }

  L.push("logsource:");
  var lsKeys = ["category", "product", "service"];
  var anyLs = false;
  lsKeys.forEach(function (k) {
    if (st.logsource && st.logsource[k]) { L.push("    " + k + ": " + yamlScalar(st.logsource[k])); anyLs = true; }
  });
  if (!anyLs) L.push("    # (no product / category / service set)");

  L.push("detection:");
  (st.selections || []).forEach(function (sel) {
    L.push("    " + (sel.name || "selection") + ":");
    var rows = (sel.rows || []).filter(function (r) { return (r.field && r.field.trim()) || (r.value && r.value.trim()); });
    if (!rows.length) { L.push("        # (no fields)"); return; }
    rows.forEach(function (r) {
      var key = (r.field || "").trim();
      if (r.op && r.op !== "equals") key += "|" + r.op;
      var val = r.value != null ? r.value : "";
      var parts = String(val).split("\n").filter(function (x) { return x.trim() !== ""; });
      if (parts.length > 1) {
        L.push("        " + key + ":");
        parts.forEach(function (p) { L.push("            - " + yamlScalar(p)); });
      } else {
        L.push("        " + key + ": " + yamlScalar(parts.length ? parts[0] : val));
      }
    });
  });
  L.push("    condition: " + yamlScalar(st.condition || ""));

  if (st.falsepositives && st.falsepositives.length) {
    L.push("falsepositives:");
    st.falsepositives.forEach(function (f) { L.push("    - " + yamlScalar(f)); });
  }
  if (st.level) L.push("level: " + st.level);
  if (st.tags && st.tags.length) {
    L.push("tags:");
    st.tags.forEach(function (t) { L.push("    - " + tagForTech(t)); });
  }
  return L.join("\n") + "\n";
}

// ── validation ──
function validate(st) {
  var problems = [];
  if (!st.title || !st.title.trim()) problems.push("Title is required.");
  if (!st.id || !/^[0-9a-f-]{36}$/i.test(st.id)) problems.push("A valid rule id (UUID) is required.");
  if (st.status && STATUSES.indexOf(st.status) < 0) problems.push("Status '" + st.status + "' is not a valid Sigma status.");
  if (!st.level) problems.push("Level is required.");
  else if (LEVELS.indexOf(st.level) < 0) problems.push("Level '" + st.level + "' is not valid.");

  var hasLs = st.logsource && (st.logsource.category || st.logsource.product || st.logsource.service);
  if (!hasLs) problems.push("logsource needs at least one of product, category or service.");

  var selNames = [];
  if (!st.selections || !st.selections.length) {
    problems.push("At least one selection block is required.");
  } else {
    st.selections.forEach(function (sel, i) {
      var nm = (sel.name || "").trim();
      if (!nm) problems.push("Selection #" + (i + 1) + " is missing a name.");
      else if (selNames.indexOf(nm) >= 0) problems.push("Duplicate selection name '" + nm + "'.");
      else selNames.push(nm);
      if (!/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(nm || "x")) problems.push("Selection name '" + nm + "' should be a simple identifier.");
      var rows = (sel.rows || []).filter(function (r) { return r.field && r.field.trim(); });
      if (!rows.length) problems.push("Selection '" + (nm || ("#" + (i + 1))) + "' has no fields with a name.");
    });
  }

  if (!st.condition || !st.condition.trim()) {
    problems.push("A condition is required.");
  } else {
    var KW = Object.assign(Object.create(null), { and: 1, or: 1, not: 1, of: 1, all: 1, any: 1, them: 1 }); // null-proto: a token "constructor"/"toString" must not resolve to an inherited member and skip the unknown-selection check
    var ids = st.condition.match(/[a-zA-Z_][a-zA-Z0-9_]*\*?/g) || [];
    ids.forEach(function (tok) {
      if (KW[tok.toLowerCase()]) return;
      var wild = tok.charAt(tok.length - 1) === "*";
      var base = wild ? tok.slice(0, -1) : tok;
      var ok = selNames.some(function (n) { return wild ? n.indexOf(base) === 0 : n === tok; });
      if (!ok) problems.push("Condition references unknown selection '" + tok + "'.");
    });
  }
  return problems;
}

